CREATE OR REPLACE FUNCTION crm.metricas_conversiones_fn(p_desde date, p_hasta date, p_origen text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_payload jsonb;
begin
  if v_actor is null or not coalesce(
    private.rol_crm(v_actor)='gerencia' or private.es_lector_global(),
    false
  ) then
    raise exception 'No autorizado' using errcode='42501';
  end if;
  v_payload:=private.metricas_conversiones_implementacion(p_desde,p_hasta,p_origen);
  return private.filtrar_desglose_sujetos_crm(
    v_payload,'responsables','vendedor_id',array['vendedor']
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.capital_autorizada(p_desde date, p_hasta date, p_medida text)
 RETURNS TABLE(tipo text, medida text, contrato_id uuid, cierre_externo_id uuid, lead_id uuid, cliente_id uuid, analista_id uuid, registrado_por uuid, en_roster boolean, moneda text, monto numeric, categoria text, mes_comercial date, fecha timestamp with time zone, fecha_vencimiento date, estado text, anulado boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid      uuid := (select auth.uid());
  v_rol      text := private.rol_crm((select auth.uid()));
  v_global   boolean;
  v_visibles uuid[] := '{}'::uuid[];
begin
  if v_uid is null then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'Periodo invalido' using errcode = '22023';
  end if;
  if p_medida is null or p_medida not in ('stock','desglose','nula') then
    raise exception 'Elige la medida: stock (el capital existe una vez), desglose (como se compone) o nula (anuladas)'
      using errcode = '22023';
  end if;
  v_global := coalesce(v_rol = 'gerencia', false) or (select private.es_lector_global());
  if not v_global then
    v_visibles := array(select private.vendedor_ids_visibles(v_uid));
    if coalesce(array_length(v_visibles, 1), 0) = 0 then
      raise exception 'No autorizado' using errcode = '42501';
    end if;
  end if;
  return query select * from private.capital_episodios(
    (p_desde::timestamp at time zone 'America/Lima'),
    ((p_hasta + 1)::timestamp at time zone 'America/Lima'),
    v_global, v_visibles) e
  where e.medida = p_medida;
end;
$function$

CREATE OR REPLACE FUNCTION private.metricas_distribucion_leads_v2_core(p_desde date, p_hasta date, p_ahora timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_sla jsonb;
  v_analistas jsonb;
begin
  v_base := private.metricas_distribucion_leads_core(p_desde, p_hasta, p_ahora);
  v_sla := private.metricas_sla_global_core(p_desde, p_hasta, p_ahora);

  v_base := jsonb_set(v_base, '{version}', '2'::jsonb);
  v_base := jsonb_set(
    v_base,
    '{cohorte}',
    (v_base->'cohorte') || jsonb_build_object(
      'criterio_sla_global', 'ciclo_sla_global_iniciado_en',
      'politica_pausas', 'SIN_DESCUENTO'
    )
  );
  v_base := jsonb_set(
    v_base,
    '{alcances}',
    ((v_base->'alcances') - 'operacion_sla') || jsonb_build_object(
      'montos', 'SEPARADOS_SIN_CONVERSION',
      'sla_principal', 'GLOBAL_POR_CICLO',
      'sla_operativo', 'POR_EPISODIO_DE_ASIGNACION'
    )
  );
  v_base := jsonb_set(
    v_base,
    '{resumen}',
    ((v_base->'resumen') - 'sla_evaluables' - 'sla_en_24h') || jsonb_build_object(
      'sla_global_ciclos_cohorte', v_sla->'cohorte_ciclos',
      'sla_global_leads_unicos_cohorte', v_sla->'cohorte_leads_unicos',
      'sla_global_contactos', v_sla->'contactos',
      'sla_global_evaluables', v_sla->'sla_evaluables',
      'sla_global_en_24h', v_sla->'sla_en_24h',
      'primer_contacto_global_mediana_minutos', v_sla->'primer_contacto_mediana_minutos',
      'sla_global_sin_contacto_vencidos_actuales', v_sla->'sin_contacto_vencidos_actuales',
      'reasignaciones_cohorte', v_sla->'reasignaciones_cohorte'
    )
  );

  select coalesce(jsonb_agg(
    jsonb_set(
      elemento,
      '{operacion}',
      ((elemento->'operacion')
        - 'contactos'
        - 'sla_evaluables'
        - 'sla_en_24h'
        - 'primer_contacto_mediana_minutos')
      || jsonb_build_object(
        'contactos_asignacion', elemento#>'{operacion,contactos}',
        'sla_asignacion_evaluables', elemento#>'{operacion,sla_evaluables}',
        'sla_asignacion_en_24h', elemento#>'{operacion,sla_en_24h}',
        'primer_contacto_asignacion_mediana_minutos',
          elemento#>'{operacion,primer_contacto_mediana_minutos}'
      )
    ) order by orden
  ), '[]'::jsonb)
  into v_analistas
  from jsonb_array_elements(v_base->'analistas') with ordinality as filas(elemento, orden);

  v_base := jsonb_set(v_base, '{analistas}', v_analistas);
  v_base := jsonb_set(
    v_base,
    '{calidad}',
    (v_base->'calidad') || jsonb_build_object(
      'ciclos_sla_global_aproximados_cohorte', v_sla->'ciclos_aproximados_cohorte'
    )
  );

  return v_base;
end;
$function$
